    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong      = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadData();
    }

    // ── LOAD DATA ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        _isLoading = true;
        StateHasChanged();

        try
        {
            // Tải song song: giáo viên + phân công chủ nhiệm
            var taskGV = TruongService.hGetDanhSachGiaoVien(maTruongBo, selectedNamHoc);
            var taskCN = TruongService.hGetThongTinChuNhiem(selectedNamHoc);
            await Task.WhenAll(taskGV, taskCN);

            AllGiaoVien = taskGV.Result;

            // Build dict: MaGiaoVien → TenLop (chủ nhiệm)
            // hGetThongTinChuNhiem trả về GiaoVienChuNhiemDTO { IdGiangVien, HoTen, IdLopHoc }
            // Để lấy tên lớp, join với lớp học — tạm dùng IdLopHoc làm key, lấy từ AllLop nếu cần
            // Ở đây service trả về MaSo (ma_so) là IdGiangVien
            _chuNhiemDict = taskCN.Result
                .Where(c => !string.IsNullOrEmpty(c.IdGiangVien))
                .GroupBy(c => c.IdGiangVien!)
                .ToDictionary(
                    g => g.Key,
                    g => g.First().HoTen ?? g.First().IdLopHoc ?? "?"
                );

            // Cần tên lớp: load riêng lớp học để map IdLopHoc → TenLop
            var danhSachLop = await TruongService.hGetDanhSachLop(
                maTruongBo, selectedCapHoc ?? "1", selectedNamHoc);
            var lopDict = danhSachLop
                .Where(l => l.IdLopBo > 0)
                .ToDictionary(l => l.IdLopBo.ToString(), l => l.TenLop);

            // Rebuild dict: MaSo GV → TenLop
            _chuNhiemDict = taskCN.Result
                .Where(c => !string.IsNullOrEmpty(c.IdGiangVien) && !string.IsNullOrEmpty(c.IdLopHoc))
                .GroupBy(c => c.IdGiangVien!)
                .ToDictionary(
                    g => g.Key,
                    g => lopDict.TryGetValue(g.First().IdLopHoc!, out var tn) ? tn : g.First().IdLopHoc!
                );

            // Gán mặc định chức vụ "Giáo viên" cho nhân sự chưa có chức vụ
            foreach (var gv in AllGiaoVien.Where(g => string.IsNullOrWhiteSpace(g.TenChucVu)))
                gv.TenChucVu = "Giáo viên";

            // Build danh sách chức vụ duy nhất
            ChucVuList = AllGiaoVien
                .Select(g => g.TenChucVu!)
                .Distinct()
                .OrderBy(x => x)
                .ToList();

            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadData error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách nhân sự!", "toast-error", "error");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER ──
    private void ApplyFilter()
    {
        if (AllGiaoVien == null) { FilteredList = new(); DisplayList = new(); StateHasChanged(); return; }

        var q = AllGiaoVien.AsEnumerable();

        if (!string.IsNullOrEmpty(_filterChucVu))
            q = q.Where(g => GetChucVu(g) == _filterChucVu);

        if (!string.IsNullOrEmpty(_filterGioiTinh))
            q = q.Where(g => g.GioiTinh == _filterGioiTinh);

        if (!string.IsNullOrWhiteSpace(_searchTerm))
        {
            var t = _searchTerm.Trim();
            q = q.Where(g =>
                (g.HoTen?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (g.MaSo?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (g.SoDienThoai?.Contains(t) == true) ||
                (g.Email?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        FilteredList = q.OrderBy(g => g.HoTen).ToList();
        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        DisplayList = FilteredList
            .Skip((currentPage - 1) * pageSize)
            .Take(pageSize)
            .ToList();
    }

    // ── PAGINATION ──
    private void OnPageChanged(int page)
    {
        currentPage = page;
        BuildPagedList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        pageSize = size; currentPage = 1;
        BuildPagedList(); StateHasChanged();
    }

