    // ── AVATAR ──
    /// URL ảnh đại diện giáo viên — cùng pattern với GetAvatarUrl học sinh
    private string GetAvatarUrl(GiaoVienDTO gv)
    {
        if (string.IsNullOrWhiteSpace(maTruongBo) || string.IsNullOrWhiteSpace(gv.MaSo))
            return "../image/avtmacdinh.jpg";
        var url = $"https://face.titkul.com/ImageFace/{maTruongBo}/{gv.MaSo}.jpg";
        return _forceReloadAvatar ? $"{url}?v={DateTime.Now.Ticks}" : url;
    }

    private void OpenAvatarModal(GiaoVienDTO gv)
    {
        _avatarTarget       = gv;
        _selectedAvatarFile = null;
        _previewUrl         = null;
        _avatarFileError    = "";
        _showAvatarModal    = true;
        _showDetailModal    = false;  // đóng detail nếu đang mở
    }

    private void CloseAvatarModal()
    {
        _showAvatarModal    = false;
        _avatarTarget       = null;
        _selectedAvatarFile = null;
        _previewUrl         = null;
        _avatarFileError    = "";
    }

    private async Task OnAvatarFileSelected(InputFileChangeEventArgs e)
    {
        _avatarFileError    = "";
        _selectedAvatarFile = null;
        _previewUrl         = null;

        var file = e.File;
        var ext  = Path.GetExtension(file.Name).ToLowerInvariant();

        if (ext != ".jpg" && ext != ".jpeg")
        {
            _avatarFileError = "Chỉ chấp nhận file JPG/JPEG!";
            return;
        }
        const long maxBytes = 100 * 1024;
        if (file.Size > maxBytes)
        {
            _avatarFileError = $"File quá lớn ({file.Size / 1024} KB). Vui lòng chọn ảnh nhỏ hơn 100 KB.";
            return;
        }

        _selectedAvatarFile = file;

        try
        {
            await using var stream = file.OpenReadStream(maxBytes);
            using var ms = new MemoryStream();
            await stream.CopyToAsync(ms);
            _previewUrl = $"data:image/jpeg;base64,{Convert.ToBase64String(ms.ToArray())}";
        }
        catch (Exception ex)
        {
            _previewUrl      = null;
            _avatarFileError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }

        StateHasChanged();
    }

    private async Task SaveNewAvatar()
    {
        if (_avatarTarget == null || _selectedAvatarFile == null) return;

        _isSavingAvatar = true;
        StateHasChanged();

        try
        {
            using var content    = new MultipartFormDataContent();
            const long maxStream = 100 * 1024;
            var stream           = _selectedAvatarFile.OpenReadStream(maxStream);
            var fileContent      = new StreamContent(stream);
            fileContent.Headers.ContentType =
                new System.Net.Http.Headers.MediaTypeHeaderValue("image/jpeg");
            content.Add(fileContent, "\"file\"", _selectedAvatarFile.Name);

            var url = $"https://upload-face.titkul.edu.vn/service_uploadFace/upload" +
                      $"?matruongbo={Uri.EscapeDataString(maTruongBo ?? "")}" +
                      $"&ma_user={Uri.EscapeDataString(_avatarTarget.MaSo ?? "")}" +
                      $"&ho_ten={Uri.EscapeDataString(_avatarTarget.HoTen ?? "")}";

            var response = await httpClient.PostAsync(url, content);
            if (response.IsSuccessStatusCode)
            {
                _forceReloadAvatar = true;
                CloseAvatarModal();
                await ShowToast("Cập nhật ảnh thành công!", "toast-success", "check_circle");
            }
            else
            {
                _avatarFileError = $"Lỗi server ({(int)response.StatusCode}). Vui lòng thử lại.";
            }
        }
        catch (Exception ex)
        {
            _avatarFileError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isSavingAvatar = false;
            StateHasChanged();
        }
    }

    // ── HELPERS ──
    /// Trả về chức vụ; nếu rỗng/null → mặc định "Giáo viên"
    private string GetChucVu(GiaoVienDTO gv)
        => string.IsNullOrWhiteSpace(gv.TenChucVu) ? "Giáo viên" : gv.TenChucVu;

    /// Trả về tên lớp chủ nhiệm của GV, null nếu không chủ nhiệm lớp nào
    private string? GetTenLopCN(string? maSo)
        => !string.IsNullOrEmpty(maSo) && _chuNhiemDict.TryGetValue(maSo, out var lop) ? lop : null;

    // ── XUẤT EXCEL ──
    private async Task ExportExcel()
    {
        if (AllGiaoVien == null || AllGiaoVien.Count == 0) return;
        try
        {
            using var wb = new XLWorkbook();
            var ws = wb.Worksheets.Add("Danh sách nhân sự");

            // Tiêu đề
            ws.Cell(1, 1).Value = $"DANH SÁCH NHÂN SỰ — NĂM HỌC {selectedNamHoc} — {tenTruong}";
            ws.Range(1, 1, 1, 8).Merge().Style
                .Font.SetBold(true).Font.SetFontSize(13)
                .Alignment.SetHorizontal(XLAlignmentHorizontalValues.Center)
                .Fill.SetBackgroundColor(XLColor.FromHtml("#6366f1"))
                .Font.SetFontColor(XLColor.White);

            // Header cột
            var headers = new[] { "STT", "Mã GV", "Họ và tên", "Giới tính", "Ngày sinh", "Chức vụ", "Chủ nhiệm lớp", "Điện thoại", "Email" };
            for (int c = 0; c < headers.Length; c++)
            {
                var cell = ws.Cell(2, c + 1);
                cell.Value = headers[c];
                cell.Style
                    .Font.SetBold(true)
                    .Fill.SetBackgroundColor(XLColor.FromHtml("#e0e7ff"))
                    .Alignment.SetHorizontal(XLAlignmentHorizontalValues.Center)
                    .Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            }

            // Dữ liệu
            var sorted = AllGiaoVien.OrderBy(g => g.HoTen).ToList();
            for (int i = 0; i < sorted.Count; i++)
            {
                var gv  = sorted[i];
                int row = i + 3;
                ws.Cell(row, 1).Value = i + 1;
                ws.Cell(row, 2).Value = gv.MaSo;
                ws.Cell(row, 3).Value = gv.HoTen;
                ws.Cell(row, 4).Value = gv.GioiTinh == "1" ? "Nam" : "Nữ";
                ws.Cell(row, 5).Value = gv.NgaySinh?.ToString("dd/MM/yyyy") ?? "";
                ws.Cell(row, 6).Value = GetChucVu(gv);
                ws.Cell(row, 7).Value = GetTenLopCN(gv.MaSo) ?? "";
                ws.Cell(row, 8).Value = gv.SoDienThoai ?? "";
                ws.Cell(row, 9).Value = gv.Email ?? "";

                // Tô vàng nhạt nếu là chủ nhiệm
                if (GetTenLopCN(gv.MaSo) != null)
                    ws.Range(row, 1, row, 9).Style.Fill.SetBackgroundColor(XLColor.FromHtml("#fefce8"));

                ws.Range(row, 1, row, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Hair);
            }

            // Column width
            ws.Column(1).Width = 6;
            ws.Column(2).Width = 16;
            ws.Column(3).Width = 28;
            ws.Column(4).Width = 10;
            ws.Column(5).Width = 14;
            ws.Column(6).Width = 20;
            ws.Column(7).Width = 16;
            ws.Column(8).Width = 16;
            ws.Column(9).Width = 26;

            // Export
            using var ms = new System.IO.MemoryStream();
            wb.SaveAs(ms);
            var base64   = Convert.ToBase64String(ms.ToArray());
            var fileName = $"NhanSu_{selectedNamHoc}_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
            await JS.InvokeVoidAsync("downloadFileFromBase64", fileName, base64);
            await ShowToast("Xuất Excel thành công!", "toast-success", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExportExcel error: {ex.Message}");
            await ShowToast("Xuất Excel thất bại!", "toast-error", "error");
        }
    }

